  try{const result=await api('songsearch',{query});if(!addCurrent(add,form,request)||state.addKind!=='youtube')return;
   if(!Array.isArray(result.items))throw new Error('Не получилось получить результаты. Повтори поиск.');
   add.items=result.items.slice(0,10).filter(item=>item&&typeof item.videoId==='string'&&/^[A-Za-z0-9_-]{11}$/.test(item.videoId)&&typeof item.title==='string'&&item.title.trim()).map(item=>({videoId:item.videoId,title:item.title.slice(0,300),channel:String(item.channel||'YouTube').slice(0,200),duration:Number.isFinite(item.duration)&&item.duration>0&&item.duration<=7200?item.duration:null})).filter((item,index,list)=>list.findIndex(other=>other.videoId===item.videoId)===index);
  }catch(error){if(addCurrent(add,form,request))add.error=error.message||'Поиск недоступен. Попробуй ещё раз.';}
  finally{if(addCurrent(add,form,request)){add.loading=false;paintSearchResults(add);updateAddAction(add);}}
