  el.innerHTML=t.importing?`<div class="enm-import-status" role="status"><span class="enm-import-spinner"></span><div><b>${h(t.stage?.label||'Готовлю текст')}</b>${t.stage?.stage==='queued'?'<small>Жду завершения предыдущей загрузки</small>':''}</div></div>`:t.importError?`<div class="enm-import-status enm-import-error" role="status"><span>${h(t.importError)}</span><button data-enm="${needsTranslation?'retry-translation':'import'}">${needsTranslation?'Повторить перевод':'Повторить'}</button></div>`:needsTranslation?'<div class="enm-import-status" role="status"><span>Английский текст готов</span><button data-enm="retry-translation">Перевести</button></div>':'';
